const __pageData = JSON.parse('{"title":"Jeffrey Epstein","description":"","frontmatter":{"title":"Jeffrey Epstein","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["epstein","doj","trafficking","media-narrative"],"sources":["raw/badlands-brief-05f.md","raw/badlands-brief-174.md","raw/badlands-brief-40d.md","raw/badlands-brief-314.md","raw/badlands-brief-4ec.md","raw/badlands-brief-52f.md","raw/badlands-brief-6f4.md","raw/badlands-brief-ac2.md","raw/badlands-brief-8db.md","raw/badlands-brief-f17.md","raw/badlands-brief-e9e.md","raw/badlands-news-blast.md","raw/badlands-news-brief-024.md","raw/badlands-news-brief-070.md","raw/badlands-news-brief-066.md","raw/badlands-news-brief-13b.md","raw/badlands-news-brief-12a.md","raw/badlands-news-brief-1d7.md","raw/badlands-news-brief-201.md","raw/badlands-news-brief-1e6.md","raw/badlands-news-brief-228.md","raw/badlands-news-brief-252.md","raw/badlands-news-brief-27c.md","raw/badlands-news-brief-33b.md","raw/badlands-news-brief-378.md","raw/badlands-news-brief-550.md","raw/badlands-news-brief-582.md","raw/badlands-news-brief-6af.md","raw/badlands-news-brief-6db.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/jeffrey-epstein.md","filePath":"entities/jeffrey-epstein.md","lastUpdated":null}');
